export type HexColorInputProps = {
  value: string;
  onChange?: (value: string) => void;
  alpha?: boolean;
};

const getHexValue = (value: string, alpha: boolean = false) => {
  return alpha ? new TinyColor(value).toHex8() : new TinyColor(value).toHex();
};

const HexColorInput: FC<HexColorInputProps> = ({ value, onChange, alpha }) => {
  const [hexValue, setHexValue] = useState<string>(value);
  const focusRef = useRef<boolean>(false);

  const handleChange: InputProps['onChange'] = (e) => {
    setHexValue(e.target.value);
    onChange?.(getHexValue(e.target.value, alpha));
  };

  const handleBlur: InputProps['onBlur'] = (e) => {
    focusRef.current = false;
    setHexValue(getHexValue(e.target.value, alpha));
  };

  const handleFocus = () => {
    focusRef.current = true;
  };

  useEffect(() => {
    if (!focusRef.current) {
      setHexValue(getHexValue(value, alpha));
    }
  }, [value, alpha]);

  return (
    <div>
      <Input
        prefix="#"
        size="small"
        value={hexValue}
        onFocus={handleFocus}
        onChange={handleChange}
        onBlur={handleBlur}
      />
      <div className="color-panel-mode-title">HEX{alpha ? '8' : ''}</div>
    </div>
  );
};

type RgbaColor = tinycolor.ColorFormats.RGBA;

export type RgbColorInputProps = {
  value?: RgbaColor;
  onChange?: (value: RgbaColor) => void;
  alpha?: boolean;
};

const RgbColorInput: FC<RgbColorInputProps> = ({
  value: customValue,
  onChange,
  alpha,
}) => {
  const [value, setValue] = useMergedState<RgbaColor>(
    customValue ?? { r: 0, g: 0, b: 0, a: 1 },
    {
      value: customValue,
      onChange,
    },
  );

  return (
    <div className="color-panel-rgba-input">
      <ConfigProvider
        theme={{ components: { InputNumber: { handleWidth: 12 } } }}
      >
        <div className="color-panel-rgba-input-part">
          <InputNumber
            min={0}
            max={255}
            size="small"
            value={value.r}
            onChange={(v) => setValue({ ...value, r: v ?? 0 })}
          />
          <div className="color-panel-mode-title">R</div>
        </div>
        <div className="color-panel-rgba-input-part">
          <InputNumber
            min={0}
            max={255}
            size="small"
            value={value.g}
            onChange={(v) => setValue({ ...value, g: v ?? 0 })}
          />
          <div className="color-panel-mode-title">G</div>
        </div>
        <div className="color-panel-rgba-input-part">
          <InputNumber
            min={0}
            max={255}
            size="small"
            value={value.b}
            onChange={(v) => setValue({ ...value, b: v ?? 0 })}
          />
          <div className="color-panel-mode-title">B</div>
        </div>
        {alpha && (
          <div className="color-panel-rgba-input-part">
            <InputNumber
              min={0}
              max={1}
              step={0.01}
              size="small"
              value={value.a}
              onChange={(v) => setValue({ ...value, a: v ?? 0 })}
            />
            <div className="color-panel-mode-title">A</div>
          </div>
        )}
      </ConfigProvider>
    </div>
  );
};

export type ColorPanelProps = {
  color: string;
  onChange: (color: string) => void;
  alpha?: boolean;
  style?: CSSProperties;
};

const colorModes = ['HEX', 'HEX8', 'RGB', 'RGBA'] as const;

type ColorMode = (typeof colorModes)[number];

const getColorStr = (color: any, mode: ColorMode) => {
  switch (mode) {
    case 'HEX':
      return new TinyColor(color).toHexString();
    case 'HEX8':
      return new TinyColor(color).toHex8String();
    case 'RGBA':
    case 'RGB':
    default:
      return new TinyColor(color).toRgbString();
  }
};

const ColorPanel: FC<ColorPanelProps> = ({ color, onChange, alpha, style }) => {
  const { token } = useToken();
  const hashId = useStyle();
  const [colorMode, setColorMode] = React.useState<ColorMode>('HEX');

  const presetColors = useMemo(() => {
    return [
      token.blue,
      token.purple,
      token.cyan,
      token.green,
      token.magenta,
      token.pink,
      token.red,
      token.orange,
      token.yellow,
      token.volcano,
      token.geekblue,
      token.gold,
      token.lime,
      '#000',
    ];
    /* eslint-disable-next-line react-hooks/exhaustive-deps */
  }, []);

  const handleColorModeChange = (value: ColorMode) => {
    setColorMode(value);
    onChange(getColorStr(color, value));
  };

  return (
    <div className={clsx(hashId, 'color-panel')} style={style}>
      {(colorMode === 'HEX' || colorMode === 'RGB') && (
        <HexColorPicker
          style={{ height: 160 }}
          color={new TinyColor(color).toHex()}
          onChange={(value) => {
            onChange(getColorStr(value, colorMode));
          }}
        />
      )}
      {(colorMode === 'RGBA' || colorMode === 'HEX8') && (
        <RgbaColorPicker
          style={{ height: 160 }}
          color={new TinyColor(color).toRgb()}
          onChange={(value) => {
            onChange(getColorStr(value, colorMode));
          }}
        />
      )}
      <div style={{ marginTop: 12 }}>
        <div className="color-panel-mode">
          <div className="color-panel-preview">
            <div
              style={{ backgroundColor: color, width: '100%', height: '100%' }}
            />
          </div>
          <Select
            value={colorMode}
            onChange={handleColorModeChange}
            options={colorModes
              .filter((item) => alpha || item === 'HEX' || item === 'RGB')
              .map((item) => ({ value: item, key: item }))}
            size="small"
            variant="borderless"
            popupMatchSelectWidth={false}
          />
        </div>
        {colorMode === 'HEX' && (
          <HexColorInput
            value={new TinyColor(color).toHex()}
            onChange={(v) => onChange?.(new TinyColor(v).toHexString())}
          />
        )}
        {colorMode === 'HEX8' && (
          <HexColorInput
            alpha
            value={new TinyColor(color).toHex8()}
            onChange={(v) => onChange?.(new TinyColor(v).toHex8String())}
          />
        )}
        {(colorMode === 'RGBA' || colorMode === 'RGB') && (
          <RgbColorInput
            alpha={colorMode === 'RGBA'}
            value={new TinyColor(color).toRgb()}
            onChange={(v) => onChange?.(new TinyColor(v).toRgbString())}
          />
        )}
      </div>
      <div className="color-panel-preset-colors">
        {presetColors.map((presetColor) => (
          <button
            key={presetColor}
            className="color-panel-preset-color-btn"
            style={{ backgroundColor: presetColor }}
            onClick={() => onChange(presetColor)}
          />
        ))}
      </div>
    </div>
  );
};

export default ColorPanel;
